                    &lt;Description&gt;Enable WinRM service&lt;/Description&gt;
                    &lt;RequiresUserInput&gt;true&lt;/RequiresUserInput&gt;
                &lt;/SynchronousCommand&gt;
            &lt;/FirstLogonCommands&gt;
            &lt;OOBE&gt;
                &lt;HideEULAPage&gt;true&lt;/HideEULAPage&gt;
