- name: Change SSL Certificate bindings
  hosts: cvad-ddcs
  gather_facts: no
  collections:
    - community.windows
  vars:
    domain_user: "TACG\\XxXxXxXxX"
    domain_pass: "!XxXxXxXxXxXxXxXxX!"
